Here is the commit message:
md/raid10: fix divide-by-zero in setup_geo() with zero
 far_copies

setup_geo() extracts near_copies (nc) and far_copies (fc) from the
user-provided layout parameter without checking for zero. When fc=0
with the "improved" far set layout selected, 'geo->far_set_size =
disks / fc' triggers a divide-by-zero.

Validate nc and fc immediately after extraction, returning -1 if
either is zero.

Fixes: 475901aff158 ("MD RAID10: Improve redundancy for 'far' and 'offset' algorithms (part 1)")
Cc: stable@vger.kernel.org
Signed-off-by: Junrui Luo <moonafterrain@outlook.com>
Link: https://lore.kernel.org/linux-raid/SYBPR01MB7881A5E2556806CC1D318582AF232@SYBPR01MB7881.ausprd01.prod.outlook.com
Signed-off-by: Yu Kuai <yukuai@fnnas.com>

Here is the root cause:
The setup_geo() function in raid10.c extracts near_copies and far_copies from the user-provided layout parameter without checking for zero values. When far_copies is zero, the subsequent division geo->far_set_size = disks / fc results in a divide-by-zero error.

Here is the patch:
 enum geo_type {geo_new, geo_old, geo_start};
 static int setup_geo(struct geom *geo, struct mddev *mddev, enum geo_type new)
 {
 	int nc, fc, fo;
 	int layout, chunk, disks;
 	switch (new) {
 	case geo_old:
 		layout = mddev->layout;
 		chunk = mddev->chunk_sectors;
 		disks = mddev->raid_disks - mddev->delta_disks;
 		break;
 	case geo_new:
 		layout = mddev->new_layout;
 		chunk = mddev->new_chunk_sectors;
 		disks = mddev->raid_disks;
 		break;
 	default: /* avoid 'may be unused' warnings */
 	case geo_start: /* new when starting reshape - raid_disks not
 			 * updated yet. */
 		layout = mddev->new_layout;
 		chunk = mddev->new_chunk_sectors;
 		disks = mddev->raid_disks + mddev->delta_disks;
 		break;
 	}
 	if (layout >> 19)
 		return -1;
 	if (chunk < (PAGE_SIZE >> 9) ||
 	    !is_power_of_2(chunk))
 		return -2;
 	nc = layout & 255;
 	fc = (layout >> 8) & 255;
 	fo = layout & (1<<16);
+	if (!nc || !fc)
+		return -1;
 	geo->raid_disks = disks;
 	geo->near_copies = nc;
 	geo->far_copies = fc;
 	geo->far_offset = fo;
 	switch (layout >> 17) {
 	case 0:	/* original layout.  simple but not always optimal */
 		geo->far_set_size = disks;
 		break;
 	case 1: /* "improved" layout which was buggy.  Hopefully no-one is
 		 * actually using this, but leave code here just in case.*/
 		geo->far_set_size = disks/fc;
 		WARN(geo->far_set_size < fc,
 		     "This RAID10 layout does not provide data safety - please backup and create new array\n");
 		break;
 	case 2: /* "improved" layout fixed to match documentation */
 		geo->far_set_size = fc * nc;
 		break;
 	default: /* Not a valid layout */
 		return -1;
 	}
 	geo->chunk_mask = chunk - 1;
 	geo->chunk_shift = ffz(~chunk);
 	return nc*fc;
 }



